export function canonicalName(kind, name, scope) {
  const alias = CONTENT_ALIASES.find(
    (x) =>
      x.kind === kind && x.from === name && (!x.scope || x.scope === scope),
  );
  return alias?.to || name;
}
export function canonicalRuleName(name) {
  let n = canonicalName("rule-name", name);
  const match = n.match(/^([^()]+?) \((.*)\)$/);
  if (match) {
    const b = canonicalName("rule-base", match[1]);
    const special = canonicalName("rule-specialisation", match[2]);
    n = `${b} (${special})`;
  }
  return n;
}
export function resolveContent(R, { kind, contentId, name, scope }) {
  const entries = Array.isArray(R[kind])
    ? R[kind]
    : Object.values(R[kind] || {}).filter(
        (x) => x && typeof x === "object" && !Array.isArray(x),
      );
  const canonical = canonicalName(kind, canonicalRuleName(name || ""), scope);
  const matches = entries.filter((x) =>
    contentId
      ? x.contentId === contentId
      : (x.name === canonical ||
          (kind === "talents" &&
            x.name.replace(/ \(.*$/, "") ===
              canonical.replace(/ \(.*$/, ""))) &&
        (!scope || x.source.book === scope || x.source.book === "core"),
  );
  if (matches.length !== 1)
    throw Error(
      `Content reference ${kind}:${contentId || name} is ${matches.length ? "ambiguous" : "unavailable"}; use an active contentId.`,
    );
  return matches[0];
}
export function validateAliases(aliases, bookIds) {
  const seen = new Set();
  for (const x of aliases) {
    const key = `${x.kind}:${x.scope || "*"}:${x.from}`;
    if (
      ![
        "gear-weight",
        "gear-profile",
        "rule-name",
        "rule-base",
        "rule-specialisation",
        "rune-form",
        "talents",
        "skills",
        "careers",
        "spells",
      ].includes(x.kind) ||
      !x.from ||
      !x.to ||
      !x.reason ||
      !bookIds.includes(x.source?.book) ||
      !x.source.page ||
      (x.scope && !bookIds.includes(x.scope)) ||
      seen.has(key) ||
      x.from === x.to
    )
      throw Error("Invalid or duplicate content alias " + key);
    seen.add(key);
  }
  for (const x of aliases) {
    let current = x.to,
      trail = new Set([x.from]);
    while (true) {
      if (trail.has(current)) throw Error("Content alias cycle");
      trail.add(current);
      const next = aliases.find(
        (y) => y.kind === x.kind && y.scope === x.scope && y.from === current,
      );
      if (!next) break;
      current = next.to;
    }
  }
  return aliases;
}

export function validateAliasTargets(aliases, entries, config) {
  const base = (n) => n.replace(/ \(.*$/, "");
  for (const x of aliases) {
    let valid;
    if (x.kind === "rune-form")
      valid = entries.some(
        (e) => e.contentKind === "runes" && e.form + " Runes" === x.to,
      );
    else if (x.kind === "rule-specialisation")
      valid = entries.some(
        (e) => e.contentKind === "skills" && e.options?.includes(x.to),
      );
    else if (["rule-name", "rule-base", "talents"].includes(x.kind))
      valid = entries.some(
        (e) => e.contentKind === "talents" && base(e.name) === base(x.to),
      );
    else if (x.kind === "skills")
      valid = entries.some(
        (e) => e.contentKind === "skills" && base(e.name) === base(x.to),
      );
    else if (x.kind === "careers")
      valid = entries.some(
        (e) => e.contentKind === "careers" && e.name === x.to,
      );
    else if (x.kind === "spells")
      valid = entries.some((e) => e.contentKind === x.kind && e.name === x.to);
    else
      valid =
        Object.hasOwn(config.gearEnc || {}, x.to) ||
        entries.some(
          (e) =>
            ["gear", "market", "weapons", "armour"].includes(e.contentKind) &&
            e.name === x.to,
        );
    if (!valid) throw Error("Content alias target unavailable: " + x.to);
  }
  return aliases;
}
